// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StorageWrite) predicate.StorageWrite {
	return predicate.StorageWrite(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StorageWrite) predicate.StorageWrite {
	return predicate.StorageWrite(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StorageWrite) predicate.StorageWrite {
	return predicate.StorageWrite(sql.NotPredicates(p))
}
